/**
 * Hand-written travel-season overrides per city.
 * `r`: ratings for January–December, one character each: `+` best, `o` fair, `-` not ideal.
 *      `.` (or omitting `r`) keeps the weather-based rule in season.ts for that month.
 * `n`: note as 'ko|en' for things the weather table cannot show (crowds, closures, events).
 */
export const SEASON_NOTES: Record<string, { r?: string; n?: string }> = {
  // France, Monaco
  paris: { r: '--oo++oo+o--', n: '8월은 현지인 휴가철이라 문 닫는 식당이 많습니다.|Many restaurants close in August while locals are on holiday.' },
  lyon: { n: '12월 초 빛의 축제 기간에는 숙소가 일찍 찹니다.|Rooms sell out early for the Festival of Lights in early December.' },
  marseille: { n: '6~9월에는 산불 위험으로 카랑크 출입이 제한되는 날이 있습니다.|In June–September the Calanques can close on high fire-risk days.' },
  strasbourg: { r: '-ooo++++++oo', n: '11월 말~12월은 크리스마스 마켓 철이라 춥지만 가장 붐빕니다.|Late November and December are cold but busiest, thanks to the Christmas markets.' },
  avignon: { n: '7월 연극제 기간에는 숙박비가 오르고 매우 붐빕니다.|Prices and crowds peak during the July theatre festival.' },
  nimes: { n: '오순절 페리아(5~6월)와 9월 페리아 때 숙소가 빨리 찹니다. 여름 한낮은 매우 덥습니다.|Rooms fill fast during the Pentecost (May–June) and September ferias; summer afternoons are very hot.' },
  'aigues-mortes': { n: '7~8월은 매우 붐비고 저녁에는 모기가 많습니다.|July and August are very busy, with plenty of mosquitoes in the evening.' },
  sete: { n: '8월 말 생루이 축제 때 운하에서 배 위 창 시합이 열려 붐빕니다.|In late August the Saint-Louis festival brings water jousting to the canals and big crowds.' },
  collioure: { n: '7~8월은 매우 붐비고 주차가 어려워 기차로 가는 편이 편합니다.|July and August are very crowded and parking is hard; the train is easier.' },
  perpignan: { n: '성금요일 산치 행렬 때 구시가가 붐빕니다. 여름은 덥고 해변 쪽이 붐빕니다.|The Good Friday Sanch procession fills the old town; summers are hot and the beaches busy.' },
  narbonne: { n: '여름에는 덥고 붐비지만 해변(나르본플라주)과 함께 다니기 좋습니다.|Summer is hot and busy but pairs well with the beach at Narbonne-Plage.' },
  carcassonne: { n: '7~8월은 매우 붐빕니다. 7월 14일에는 시테 불꽃놀이가 열려 숙소가 빨리 찹니다.|July and August are very busy; the Cité fireworks on 14 July fill rooms fast.' },
  'moustiers-sainte-marie': { n: '11월~3월에는 가게와 숙소가 많이 쉽니다. 발랑솔 라벤더 밭은 보통 6월 말~7월 중순에 핍니다.|Many shops and hotels close from November to March; the Valensole lavender usually flowers late June to mid-July.' },
  cassis: { n: '6~9월에는 산불 위험으로 칼랑크 출입이 제한되는 날이 있습니다. 여름 주말에는 주차가 매우 어렵습니다.|In June–September the Calanques can close on high fire-risk days; parking is very hard on summer weekends.' },
  'isle-sur-la-sorgue': { n: '일요일 시장 날에는 아침 일찍 가야 주차할 수 있습니다. 부활절과 8월 중순에는 큰 골동품 박람회가 열립니다.|On Sunday market days arrive early to park; big antiques fairs are held at Easter and in mid-August.' },
  gordes: { n: '라벤더 철(6월 말~7월 중순)과 여름에는 매우 붐빕니다. 세낭크 수도원 주차장도 일찍 찹니다.|Very busy in lavender season (late June to mid-July) and summer; the Sénanque car park fills early.' },
  'les-baux-de-provence': { n: '여름 한낮에는 매우 붐비고 주차비가 비쌉니다. 아침이나 늦은 오후에 가는 편이 좋습니다.|Summer middays are very crowded and parking is pricey; go early or late in the day.' },
  arles: { n: '7월 초 아를 사진 축제(Rencontres d\'Arles, 전시는 10월 초까지) 개막 주간과 부활절·9월 페리아 때 숙소가 빨리 찹니다.|Rooms fill fast during the opening week of the photography festival in early July (exhibitions run to early October) and the Easter and September ferias.' },
  menton: { n: '2월 레몬 축제(페트 뒤 시트롱) 때 숙소가 빨리 찹니다.|Rooms go fast during the February Lemon Festival (Fête du Citron).' },
  grasse: { n: '5월 장미 축제(엑스포 로즈)와 8월 재스민 축제 때 가장 향기롭습니다.|Best smelt during the May rose show (Expo Rose) and the August jasmine festival.' },
  'saint-tropez': { n: '7~8월은 매우 붐비고 숙박비가 비쌉니다. 기차역이 없어 생라파엘에서 버스나 배로 갑니다.|July and August are very crowded and pricey; there is no station, so come by bus or boat from Saint-Raphaël.' },
  'aix-en-provence': { n: '7월 엑상프로방스 오페라 축제 때 숙소가 빨리 찹니다. 세잔 아틀리에는 예약이 필요합니다.|Rooms go fast during the July opera festival; Cézanne’s studio needs booking.' },
  alula: { n: '10~3월이 좋고, 겨울밤은 쌀쌀합니다. 여름 낮은 40℃를 넘습니다.|October–March is best, with chilly winter nights; summer days pass 40 °C.' },
  jeddah: { n: '11~3월이 좋습니다. 해안이라 습하고, 여름엔 덥고 끈적입니다.|November–March is best; the coast is humid, and summers are hot and sticky.' },
  riyadh: { n: '11~2월이 선선해 좋고, 5~9월은 45℃에 이릅니다. 라마단 기간엔 낮에 식당이 문을 닫습니다.|November–February is pleasantly cool; May–September reaches 45 °C. Restaurants close by day during Ramadan.' },
  'al-ain': { n: '11~3월이 좋습니다. 내륙이라 해안보다 건조하고 여름 낮엔 45℃를 넘습니다.|November–March is best; inland, it is drier than the coast and summer days pass 45 °C.' },
  'abu-dhabi': { n: '11~3월이 좋고, 한여름은 45℃에 이릅니다.|November–March is best; midsummer reaches 45 °C.' },
  dubai: { n: '11~3월이 선선해 좋고, 6~9월은 40℃를 훌쩍 넘습니다. 라마단 기간엔 낮에 식당이 문을 닫거나 가려서 엽니다.|November–March is pleasantly cool; June–September soars past 40 °C. During Ramadan many restaurants close or screen off by day.' },
  'dead-sea': { n: '여름 낮은 40℃를 넘으니 아침 일찍 다니세요. 10~4월이 좋습니다.|Summer days exceed 40 °C, so go early; October–April is best.' },
  haifa: { n: '봄·가을이 좋습니다. 외교부 여행경보 4단계인 레바논 국경 4km 이내에는 가지 마세요.|Spring and autumn are best. Do not go within 4 km of the Lebanese border (Korean travel-ban area).' },
  'tel-aviv': { n: '4~10월이 해변 철이고, 한여름은 덥고 습합니다. 6월 프라이드 축제가 큽니다.|April–October is beach season; midsummer is hot and humid. The June Pride parade is huge.' },
  jerusalem: { n: '봄(3~5월)과 가을(9~11월)이 좋습니다. 겨울엔 비가 오고 가끔 눈이 내립니다. 유대교 명절과 안식일엔 문을 닫는 곳이 많습니다.|Spring (March–May) and autumn (September–November) are best; winter brings rain and occasional snow. Much closes on Jewish holidays and the Sabbath.' },
  doha: { n: '11~3월이 선선해 좋고, 6~9월은 40℃를 훌쩍 넘습니다. 라마단 기간엔 낮에 식당이 문을 닫습니다.|November–March is pleasantly cool; June–September soars past 40 °C. During Ramadan restaurants close by day.' },
  'abu-simbel': { n: '10~3월이 좋고, 여름 낮은 45℃ 가까이 오릅니다. 2월·10월 22일 태양 축제가 유명합니다.|October–March is best; summer days near 45 °C. The Sun Festival on 22 February and 22 October is famous.' },
  'kom-ombo': { n: '10~4월이 좋습니다. 크루즈는 대개 저녁에 신전을 들릅니다.|October–April is best; cruises usually visit in the evening.' },
  edfu: { n: '10~4월이 좋습니다. 크루즈는 대개 아침 일찍 신전을 들릅니다.|October–April is best; cruises usually visit the temple early in the morning.' },
  aqaba: { n: '겨울에도 따뜻해 1년 내내 바다에 들어갑니다. 여름은 매우 덥습니다.|Warm enough to swim all year; summer is very hot.' },
  'wadi-rum': { n: '10~4월이 좋습니다. 사막의 겨울밤은 영하 가까이 내려가니 따뜻한 옷을 챙기세요.|October–April is best; winter nights in the desert near freezing, so bring warm clothes.' },
  petra: { n: '3~5월과 10~11월이 걷기 좋습니다. 한여름엔 그늘이 없어 매우 덥고 겨울 아침은 춥습니다.|March–May and October–November are best for walking; summer is very hot with no shade, and winter mornings are cold.' },
  amman: { n: '3~5월과 9~11월이 좋습니다. 여름 낮은 덥고 겨울엔 눈이 오기도 합니다.|March–May and September–November are best; summer days are hot and it can snow in winter.' },
  hurghada: { n: '1년 내내 바다에 들어갈 수 있고, 여름 낮은 덥습니다. 겨울 바다는 조금 차갑습니다.|Swimmable all year; summer days are hot and the winter sea a little cool.' },
  alexandria: { n: '여름에도 바닷바람에 카이로보다 선선해 이집트 사람들의 피서지입니다. 겨울엔 비가 오기도 합니다.|Cooler than Cairo in summer thanks to the sea breeze—Egyptians’ summer resort; winter brings some rain.' },
  aswan: { n: '10~3월이 좋습니다. 여름엔 이집트에서 가장 덥습니다.|October–March is best; summer here is the hottest in Egypt.' },
  luxor: { n: '10~4월이 좋습니다. 여름 낮은 40℃를 훌쩍 넘어 아침 일찍 다니세요.|October–April is best; summer days soar past 40 °C, so start early.' },
  cairo: { n: '10~4월이 여행하기 좋고, 6~8월은 40℃를 넘기도 합니다. 라마단 기간엔 영업시간이 바뀝니다.|October–April is the best time; June–August can exceed 40 °C. Opening hours change during Ramadan.' },
  kairouan: { n: '봄·가을이 좋고 여름 낮은 40℃ 가까이 덥습니다.|Spring and autumn are best; summer days approach 40 °C.' },
  monastir: { n: '5~10월이 해변 철입니다. 한여름엔 휴양객으로 붐빕니다.|May–October is beach season; busy with holidaymakers in midsummer.' },
  sousse: { n: '5~10월이 해변 철이고 한여름은 덥습니다.|May–October is beach season; midsummer is hot.' },
  tunis: { n: '3~5월과 9~11월이 좋고, 7~8월은 덥습니다. 라마단 기간엔 낮에 문을 닫는 식당이 많습니다.|March–May and September–November are best; July and August are hot. During Ramadan many restaurants close by day.' },
  casablanca: { n: '1년 내내 온화합니다. 하산 2세 모스크는 금요일 투어가 적으니 다른 날을 고르세요.|Mild all year; pick a day other than Friday for the Hassan II Mosque tours.' },
  rabat: { n: '1년 내내 온화한 해양성 기후로, 여름에도 비교적 선선합니다.|Mild Atlantic weather all year, relatively cool even in summer.' },
  tangier: { n: '여름에도 바닷바람에 비교적 선선합니다. 겨울엔 바람과 비로 페리가 쉬기도 합니다.|Relatively cool in summer thanks to the sea; winter wind and rain sometimes cancel ferries.' },
  chefchaouen: { n: '봄·가을이 걷기 좋고, 겨울엔 산이라 춥고 비가 잦습니다.|Spring and autumn are best for walking; winters are cold and rainy in the mountains.' },
  fez: { n: '봄·가을이 좋고, 여름 낮은 덥고 겨울엔 비가 잦습니다. 6월 세계 종교 음악 축제가 열립니다.|Spring and autumn are best; summers are hot and winters rainy. The World Sacred Music Festival is in June.' },
  merzouga: { n: '10~4월이 사막 여행에 좋습니다. 겨울밤은 영하로 내려가고, 6~8월 낮은 45℃ 가까이 오릅니다.|October–April is best for the desert; winter nights fall below freezing and June–August days near 45 °C.' },
  essaouira: { n: '여름에도 바닷바람에 선선하고, 6월 그나와 음악 축제가 열립니다. 바람이 세서 겉옷이 필요합니다.|Cool sea breezes even in summer; the Gnaoua music festival is in June. Bring a layer for the wind.' },
  marrakech: { n: '3~5월과 10~11월이 걷기 좋고, 6~8월은 40℃를 넘기도 합니다. 라마단 기간엔 낮에 문을 닫는 식당이 많습니다.|March–May and October–November are best for walking; June–August can top 40 °C. During Ramadan many restaurants close in the daytime.' },
  'angra-do-heroismo': { n: '6월 말 상 주아니냐스 축제가 가장 큽니다. 날씨가 자주 바뀌니 겉옷을 챙기세요.|The Sanjoaninas festival in late June is the biggest; pack a layer for changeable weather.' },
  'ponta-delgada': { n: '1년 내내 온화하지만 날씨가 하루에도 여러 번 바뀝니다. 고래 관찰은 봄~가을이 좋습니다.|Mild all year but the weather changes several times a day; whale watching is best spring to autumn.' },
  elvas: { n: '여름 낮은 40℃ 가까이 덥습니다. 봄과 가을이 걷기에 좋습니다.|Summer afternoons can approach 40 °C; spring and autumn are best for walking.' },
  marvao: { n: '11월 밤 축제(밤나무 열매 축제)가 마을 안에서 열립니다. 겨울엔 안개가 잦습니다.|The chestnut fair fills the village in November; winter brings frequent fog.' },
  tavira: { n: '6~9월이 해변 철이고, 겨울에도 따뜻해 걷기 좋습니다.|June–September is beach season; mild winters are good for walking.' },
  monsanto: { n: '봄·가을이 걷기에 좋고, 한여름 낮은 덥습니다. 5월 첫 주말 성 축제가 열립니다.|Spring and autumn are best for walking; summer afternoons are hot. A castle festival is held on the first weekend of May.' },
  manteigas: { n: '12~3월엔 눈이 와 스키를 탑니다. 5~10월이 산길 걷기에 좋습니다. 세하 치즈는 겨울~봄이 제철입니다.|Snow and skiing December–March; May–October suits hiking. Serra cheese is best in winter and spring.' },
  ericeira: { n: '가을~봄이 큰 파도의 서핑 철이고, 여름은 초보자에게 좋습니다.|Autumn to spring brings the big surf; summer suits beginners.' },
  setubal: { n: '여름 아라비다 해변이 가장 붐빕니다. 돌고래 관찰은 1년 내내 가능합니다.|Arrábida’s beaches are busiest in summer; dolphin trips run all year.' },
  alcobaca: { n: '11월 수녀원 과자 축제가 수도원에서 열립니다.|The convent-sweets fair is held at the monastery in November.' },
  'viana-do-castelo': { n: '8월 아고니아 축제에 민속 의상 행렬과 금 장신구가 거리를 채웁니다.|In August the Agonia festival fills the streets with folk costume and gold jewellery.' },
  amarante: { n: '6월 첫 주말 상 곤살루 축제가 열립니다.|The São Gonçalo festival is held on the first weekend of June.' },
  lamego: { n: '9월 초 성모 축제(헤메디우스 축제)에 큰 행렬이 열립니다.|The Remédios festival in early September brings a great procession.' },
  'peso-da-regua': { n: '9월 말~10월 초 포도 수확철이 가장 아름답습니다. 여름 토요일엔 증기 기관차 관광 열차가 다닙니다.|Most beautiful at harvest (late September to early October); a historic steam train runs on summer Saturdays.' },
  tenerife: { n: '1년 내내 18~28℃로 온화합니다. 테이데 정상 부근은 겨울에 눈이 오고 매우 춥습니다.|Mild all year at 18–28 °C; around the summit of Teide it snows in winter and is very cold.' },
  menorca: { n: '6~9월이 해변 철입니다. 6월 말 시우타데야의 산 조안 축제에선 말들이 군중 사이로 뛰어오릅니다.|June–September is beach season; at Ciutadella’s Sant Joan fiesta in late June, horses rear up among the crowds.' },
  ibiza: { n: '6~9월이 해변 철이고 클럽은 대체로 5~10월에만 엽니다. 겨울엔 문을 닫는 곳이 많습니다.|June–September is beach season and the clubs open roughly May–October; much closes in winter.' },
  alicante: { n: '6월 23~24일 산 후안 불꽃 축제(오게라스)가 가장 큽니다. 겨울에도 온화합니다.|The Hogueras bonfire festival on 23–24 June is the biggest; winters are mild.' },
  almeria: { n: '1년 내내 맑고 건조해 겨울에도 따뜻합니다. 한여름엔 매우 덥습니다.|Sunny and dry all year, mild even in winter; midsummer is very hot.' },
  tarifa: { n: '동풍 ‘레반테’가 불면 며칠씩 바람이 거셉니다. 6~9월이 해변 철이고 고래는 4~10월입니다.|The easterly levante can blow hard for days; June–September is beach season and whales come April–October.' },
  jerez: { n: '5월 말 말 축제(페리아 델 카바요)와 9월 포도 수확 축제가 큽니다.|The Horse Fair (late May) and the September grape-harvest fiesta are the big events.' },
  ubeda: { n: '11~1월 올리브 수확철엔 방앗간이 바쁘게 돌아갑니다. 한여름은 매우 덥습니다.|The olive harvest (November–January) keeps the mills busy; midsummer is very hot.' },
  merida: { n: '여름 밤 로마 극장에서 고전극 축제(7~8월)가 열리지만 낮엔 매우 덥습니다.|The classical drama festival fills the Roman theatre on summer nights (July–August), but days are very hot.' },
  caceres: { n: '7~8월은 40℃ 가까이 덥습니다. 봄과 가을이 걷기에 좋습니다.|July and August can approach 40 °C; spring and autumn are best for walking.' },
  teruel: { n: '고원이라 겨울은 매우 춥습니다. 2월 ‘연인들의 축제’에 중세 재현 행사가 열립니다.|High and very cold in winter; the Lovers’ festival in February brings medieval re-enactments.' },
  oviedo: { n: '비가 잦은 초록의 지방입니다. 9월 산 마테오 축제와 여름 사과주 축제가 열립니다.|A green, rainy region; the San Mateo fiesta is in September and cider festivals run in summer.' },
  santander: { n: '여름에도 선선해 해변 휴가지로 인기입니다. 비가 잦으니 우산을 챙기세요.|Cool even in summer and popular for beach holidays; rain is frequent, so pack an umbrella.' },
  pamplona: { n: '7월 6~14일 산 페르민 축제 때는 숙소값이 몇 배로 뛰고 일찍 동납니다.|During San Fermín (6–14 July) hotel prices multiply and rooms sell out early.' },
  logrono: { n: '9월 하순 포도 수확 축제(산 마테오)가 가장 큽니다. 라우렐 거리는 저녁 8시 이후에 붐빕니다.|The San Mateo grape-harvest fiesta in late September is the biggest; Calle Laurel fills up after 8 pm.' },
  burgos: { n: '여름에도 저녁엔 선선하고 겨울은 매우 춥습니다. 6월 말 산 페드로 축제가 큽니다.|Evenings are cool even in summer and winters are very cold; the San Pedro fiesta in late June is the biggest.' },
  leon: { n: '6월 말 산 후안·산 페드로 축제와 성주간 행렬이 유명합니다. 겨울은 춥고 건조합니다.|Known for its Holy Week processions and the San Juan and San Pedro fiestas in late June; winters are cold and dry.' },
  corte: { n: '6월과 9월이 하이킹에 좋고, 한여름엔 레스토니카 계곡 길이 붐빕니다.|June and September are best for hiking; the Restonica road is crowded in high summer.' },
  bastia: { n: '5~6월과 9월이 해안 드라이브와 수영에 좋고, 7~8월은 페리와 숙소가 붐빕니다.|May–June and September are best for coastal drives and swimming; ferries and hotels are busy in July and August.' },
  lourdes: { n: '4~10월이 순례철로 밤 촛불 행렬이 열리고, 8월 15일 성모 승천 대축일이 가장 붐빕니다.|April–October is pilgrimage season with the nightly procession; 15 August (the Assumption) is busiest.' },
  pau: { n: '맑은 가을·겨울 아침에 피레네가 가장 또렷이 보입니다.|The Pyrenees are clearest on crisp autumn and winter mornings.' },
  'saint-jean-pied-de-port': { n: '4~10월이 순례길 철로, 봄·가을 아침엔 순례자들이 줄지어 출발합니다.|April–October is pilgrim season; on spring and autumn mornings pilgrims set off in streams.' },
  albi: { n: '봄·가을이 걷기 좋고, 여름엔 덥지만 강변 저녁이 좋습니다.|Spring and autumn are best for walking; summers are hot, but the riverside evenings are lovely.' },
  rocamadour: { n: '봄·가을이 덜 붐비고, 여름엔 낮에 단체 손님이 많아 아침저녁이 좋습니다.|Spring and autumn are quieter; in summer, visit early or late to avoid the day crowds.' },
  sarlat: { n: '12~2월 토요일엔 송로버섯 시장, 7~8월엔 연극 축제가 열립니다. 여름엔 붐빕니다.|Truffle markets run on Saturdays December–February and a theatre festival in July–August; summer is busy.' },
  'le-puy-en-velay': { n: '9월 중순 르네상스 축제 ‘새의 왕 축제’가 열리고, 봄~가을이 순례길 철입니다.|The Renaissance Roi de l’Oiseau festival is held in mid-September; spring to autumn is pilgrimage season.' },
  'clermont-ferrand': { n: '2월 국제 단편 영화제가 열리고, 늦봄~가을이 화산 하이킹철입니다.|The international short-film festival is held in February; late spring to autumn is volcano-hiking season.' },
  grenoble: { n: '겨울엔 근교 스키장의 거점이 되고, 여름엔 산악 하이킹이 좋습니다.|In winter it is a base for nearby ski resorts; in summer, for mountain hikes.' },
  nancy: { n: '12월 초 성 니콜라 축제 퍼레이드가 열리고, 여름밤엔 스타니슬라스 광장에 빛 공연을 합니다.|The Saint Nicholas parade is held in early December; summer nights bring a light show on Place Stanislas.' },
  blois: { n: '봄~가을에 성 순환 셔틀버스가 다니고, 여름밤엔 왕성에서 빛 공연을 합니다.|Château shuttle buses run spring to autumn, and the royal château has a summer-night light show.' },
  quimper: { n: '7월 말 브르타뉴 전통 음악·의상 축제 ‘코르누아이유 축제’가 열립니다.|The Festival de Cornouaille of Breton music and costume is held in late July.' },
  nantes: { n: '여름엔 도시 곳곳에 설치 미술을 놓는 ‘르 부아야주 아 낭트’가 열립니다.|In summer the Voyage à Nantes festival fills the city with art installations.' },
  lille: { n: '9월 첫 주말 거리 전체가 벼룩시장이 되는 ‘브라드리’와 겨울 크리스마스 마켓이 유명합니다.|The Braderie turns the whole city into a flea market on the first weekend of September; there is also a Christmas market.' },
  trapani: { n: '여름이 섬 여행철이고, 부활절 성금요일부터 24시간 이어지는 ‘미스테리 행렬’이 유명합니다.|Summer is island season; the 24-hour Misteri procession from Good Friday is famous.' },
  ragusa: { n: '봄·가을이 걷기 좋고, 여름엔 해변 마을 마리나 디 라구사와 함께 다닙니다.|Spring and autumn are best for walking; in summer combine it with the beach at Marina di Ragusa.' },
  ischia: { n: '온천 정원이 여는 4~10월이 좋고, 7~8월은 붐빕니다.|April–October, when the thermal gardens are open, is best; July and August are crowded.' },
  ostuni: { n: '늦봄~초가을이 해변과 함께 다니기 좋고, 10~11월은 올리브 수확철입니다.|Late spring to early autumn pairs well with the beaches; October–November is the olive harvest.' },
  spoleto: { n: '6월 말~7월 중순 음악·연극·무용 축제 ‘두 세계 축제’가 열립니다.|The Festival dei Due Mondi of music, theatre and dance runs from late June to mid-July.' },
  gubbio: { n: '5월 15일 거대한 촛대를 지고 산꼭대기까지 달리는 ‘촛대 경주’가 가장 큰 행사입니다.|The Festa dei Ceri on 15 May, racing giant wooden “candles” up the mountain, is the big event.' },
  cortona: { n: '봄·가을이 걷기 좋고, 8월 중순엔 스테이크 축제가 열립니다.|Spring and autumn are best for walking; a steak festival is held in mid-August.' },
  arezzo: { n: '매달 첫째 주말 골동품 시장이 열리고, 6월과 9월엔 중세 기마 시합 ‘사라센 기사 시합’이 열립니다.|The antiques fair runs the first weekend of every month; the Saracen Joust takes place in June and September.' },
  aosta: { n: '1월 말 장인 축제 ‘산토르소 축제’가 열리고, 여름이 몽블랑과 계곡 하이킹철입니다.|The Sant’Orso craft fair is held in late January; summer is the season for Mont Blanc and valley hikes.' },
  trento: { n: '11월 말~1월 초 크리스마스 마켓이 유명하고, 봄·가을이 걷기 좋습니다.|Its late-November-to-early-January Christmas market is well known; spring and autumn are best for walking.' },
  merano: { n: '봄 꽃과 가을 포도 수확철이 좋고, 11월 말~1월 초엔 강변에 크리스마스 마켓이 섭니다.|Spring flowers and the autumn grape harvest are lovely; a riverside Christmas market runs late November to early January.' },
  ortisei: { n: '케이블카가 다니는 6~9월이 하이킹철이고, 12~3월은 스키철입니다. 그 사이 늦봄·늦가을엔 케이블카와 호텔이 많이 쉽니다.|June–September is hiking season while the cable cars run, December–March is ski season; in late spring and late autumn many lifts and hotels close.' },
  lindau: { n: '여름이 호수 수영과 유람선철입니다. 맑은 날엔 호수 너머 알프스가 또렷이 보입니다.|Summer is the season for swimming and boat trips; on clear days the Alps stand out across the lake.' },
  freiburg: { n: '독일에서 가장 따뜻하고 해가 많은 도시로 꼽힙니다. 봄~가을이 검은 숲 산책에 좋고, 12월엔 크리스마스 마켓이 섭니다.|One of Germany’s warmest, sunniest cities; spring to autumn is best for the Black Forest, with a Christmas market in December.' },
  trier: { n: '가을 포도 수확철에 모젤 와인 축제가 이어지고, 12월엔 중앙 광장에 크리스마스 마켓이 섭니다.|Moselle wine festivals run through the autumn harvest; a Christmas market fills the Hauptmarkt in December.' },
  aachen: { n: '12월 대성당 주변 크리스마스 마켓이 유명하고, 생강 과자 ‘아헨 프린텐’을 맛봅니다.|Its December Christmas market around the cathedral is famous—try the local gingerbread, Aachener Printen.' },
  gorlitz: { n: '12월 실레지아 크리스마스 마켓이 열립니다. 국경 다리는 언제든 걸어서 건널 수 있습니다.|The Silesian Christmas market is held in December; the border bridge is open to walk across at any time.' },
  weimar: { n: '10월 둘째 주말 양파 축제(Zwiebelmarkt)가 열리고, 12월엔 크리스마스 마켓이 섭니다.|The Onion Market fair takes over the town in October; Christmas markets in December.' },
  bremen: { n: '12월 크리스마스 마켓과 10월 프라이마르크트 축제가 열립니다.|The Christmas market in December and the Freimarkt fair in October.' },
  lubeck: { n: '12월 크리스마스 마켓이 유명합니다. 여름엔 트라베뮌데 해변이 붐빕니다.|Its December Christmas markets are famous; Travemünde’s beach is busy in summer.' },
  rahovec: { n: '9월 포도 수확 축제(Vjeshta e Rahovecit) 때 가장 활기찹니다.|Liveliest at the September harvest festival.' },
  gjakova: { n: '봄~가을이 걷기 좋습니다. 여름 저녁엔 바자르 노천 카페가 붐빕니다.|Spring to autumn is best for walking; summer evenings fill the bazaar terraces.' },
  perast: { n: '7~8월엔 크루즈 손님으로 낮에 붐비니 아침이나 저녁이 좋습니다. 7월 22일엔 바위의 성모 섬 행사가 열립니다.|Cruise passengers crowd the village by day in July–August, so come early or late; the Our Lady of the Rocks festival is on 22 July.' },
  ulcinj: { n: '7~8월에 해변이 가장 붐빕니다. 봄·가을엔 염전에서 철새를 보기 좋습니다.|July–August is peak beach season; spring and autumn are best for birdwatching at the salina.' },
  zabljak: { n: '6~9월이 산행철이고, 12~3월엔 스키장이 엽니다. 여름에도 저녁은 쌀쌀합니다.|June–September is hiking season and December–March the ski season; evenings are cool even in summer.' },
  cetinje: { n: '여름에도 해안보다 선선합니다. 로브첸 산길은 겨울에 눈으로 막힐 수 있습니다.|Cooler than the coast in summer; the Lovćen road can close for snow in winter.' },
  srebrenica: { n: '7월 11일 추모식 때는 많은 사람이 찾습니다. 버스가 드물어 사라예보나 투즐라에서 투어로 오는 경우가 많습니다.|Many come for the 11 July commemoration; buses are rare, so visits are often by tour from Sarajevo or Tuzla.' },
  trebinje: { n: '여름이 덥고 건조하며, 가을엔 포도 수확철입니다. 두브로브니크가 붐비는 여름에 조용히 다녀오기 좋습니다.|Summers are hot and dry and autumn is the harvest; a quiet escape from busy summer Dubrovnik.' },
  visegrad: { n: '여름에 강 유람선이 다니고, 6월엔 안드리치그라드에서 행사가 열립니다.|River boats run in summer, and Andrićgrad hosts events in June.' },
  jajce: { n: '봄에 물이 많아 폭포가 가장 웅장합니다. 8월엔 폭포 다이빙 대회가 열립니다.|The falls are fullest in spring; a waterfall-diving contest is held in August.' },
  kraljevo: { n: '봄~가을이 수도원과 계곡을 둘러보기 좋습니다.|Spring to autumn is best for the monasteries and the valley.' },
  golubac: { n: '5~9월이 강변과 유람선에 좋습니다. 요새는 겨울에 운영 시간이 줄어듭니다.|May–September is best for the riverside and boat trips; the fortress cuts its hours in winter.' },
  'sremski-karlovci': { n: '9월 말 포도 수확 축제 ‘그로즈데발’이 열립니다. 여름 저녁엔 광장 노천 카페가 붐빕니다.|The Grožđebal grape-harvest festival is in late September; summer evenings fill the square’s terraces.' },
  zlatibor: { n: '여름(6~9월)엔 고원이 선선하고 샤르간 8이 다닙니다. 겨울엔 토르니크 스키장이 엽니다.|Summer (June–September) is cool on the plateau and the Šargan Eight runs; Tornik opens for skiing in winter.' },
  koper: { n: '여름엔 해변과 항구가 붐빕니다. 가을엔 이스트리아 올리브 수확과 와인 행사가 열립니다.|Summer crowds the beaches and harbour; autumn brings the Istrian olive harvest and wine events.' },
  bovec: { n: '5~9월이 래프팅과 산행철입니다. 여름엔 블레드 쪽에서 브르시치 고개를 넘는 길이 열립니다(겨울엔 닫힘).|May–September is the rafting and hiking season; in summer the road over the Vršič pass from the Bled side opens (closed in winter).' },
  ptuj: { n: '2월 카니발 기간에 털옷 차림의 쿠렌트가 거리를 누빕니다(유네스코 무형유산). 가을엔 포도 수확철입니다.|During the February carnival, shaggy Kurent figures parade the streets (UNESCO intangible heritage); autumn is the grape harvest.' },
  bohinj: { n: '6~9월이 호수 수영과 산행에 좋습니다. 9월엔 소 떼가 산에서 내려오는 ‘소 무도회(크라비 발)’ 축제가 열립니다. 겨울엔 보겔 스키장이 엽니다.|June–September is best for swimming and hiking; September brings the Cows’ Ball festival as herds come down from the pastures, and Vogel opens for skiing in winter.' },
  hrensko: { n: '봄~가을이 걷기 좋고 협곡 보트도 이때만 다닙니다. 2022년 큰 산불이 났던 곳이라 일부 길이 닫혀 있을 수 있습니다.|Spring to autumn is best for walking and the only season for the gorge boats; after the big 2022 forest fire some trails may be closed.' },
  znojmo: { n: '9월 즈노이모 포도 수확 축제가 가장 큽니다. 지하 미로와 로툰다는 겨울에 운영이 줄어듭니다.|The Znojmo grape-harvest festival in September is the big event; the underground and rotunda cut back in winter.' },
  'kutna-hora': { n: '6월 말 ‘은의 도시’ 중세 축제가 열립니다. 은광 투어는 겨울에 쉽니다.|The “Royal Silver” medieval festival is held in late June; the mine tour closes in winter.' },
  plzen: { n: '10월 초 필스너 페스트 등 맥주 행사가 열립니다. 12월엔 공화국 광장에 크리스마스 마켓이 섭니다.|Beer events such as Pilsner Fest are held in early October; a Christmas market fills Republic Square in December.' },
  keszthely: { n: '7~8월에 호숫가가 가장 붐빕니다. 헤비즈 온천 호수는 겨울에도 들어갈 수 있습니다.|The lakeshore is busiest in July and August; Lake Hévíz is swimmable even in winter.' },
  tokaj: { n: '9~10월 수확철에 포도 축제가 열립니다. 겨울엔 문을 닫는 와이너리가 많으니 시음은 미리 예약하세요.|The harvest festival is in September–October; many wineries close in winter, so book tastings ahead.' },
  holloko: { n: '부활절 축제 때 마을 사람들이 전통 옷을 입고 행사를 엽니다. 여름이 가장 붐빕니다.|At the Easter festival the villagers put on traditional dress; summer is busiest.' },
  sopron: { n: '여름엔 채석장 동굴 극장 공연과 와인 축제가 열립니다. 옛 유대교 회당은 겨울에 닫습니다.|Summer brings performances in the quarry cave theatre and wine festivals; the Old Synagogue closes in winter.' },
  gyor: { n: '6월 말 바로크 축제 기간에 구시가가 붐빕니다. 12월엔 세체니 광장에 크리스마스 마켓이 섭니다.|The old town is busy during the late-June Baroque festival; there is a Christmas market on Széchenyi Square in December.' },
  westport: { n: '7월 마지막 일요일 ‘리크 선데이’엔 수많은 순례자가 크로 패트릭을 오릅니다. 그린웨이는 5~9월이 자전거 타기 좋습니다.|On Reek Sunday, the last Sunday of July, crowds of pilgrims climb Croagh Patrick; May–September is best for cycling the Greenway.' },
  kinsale: { n: '여름이 항구 산책에 가장 좋고 붐빕니다. 데즈먼드 성은 여름철에만 엽니다.|Summer is the best and busiest time for the harbour walks; Desmond Castle opens only in summer.' },
  doolin: { n: '여름엔 펍마다 전통 음악 세션이 매일 열립니다. 섬과 절벽 아래 유람선은 대략 3~10월에만 다닙니다.|In summer every pub has a traditional session nightly; island boats and cliff cruises run roughly March to October.' },
  dingle: { n: '7~8월에 가장 붐비고 숙소가 빨리 찹니다. 바람과 비가 잦아 해안 도로는 맑은 날을 고르는 편이 좋습니다.|July and August are busiest and rooms fill fast; wind and rain are frequent, so save the coast road for a clear day.' },
  'fort-william': { n: '5~9월이 걷기 좋고 해가 깁니다. 여름엔 깔따구(미지)가 많아 벌레 퇴치제가 필요합니다. 자코바이트는 대략 봄~가을에만 다닙니다.|May–September brings the best walking and long days; summer midges call for repellent. The Jacobite runs roughly spring to autumn.' },
  dover: { n: '여름이 절벽 산책에 가장 좋습니다. 바람이 세고 절벽 끝은 무너지기 쉬우니 가장자리에서 떨어져 걸으세요.|Summer is best for the cliff walk; it is windy, and the edges crumble—keep well back.' },
  chester: { n: '5월 체스터 경마장의 메이 페스티벌 때 숙소가 빨리 찹니다. 12월엔 크리스마스 마켓이 열립니다.|Rooms go fast during the May Festival at Chester Racecourse; there’s a Christmas market in December.' },
  durham: { n: '12월 크리스마스 마켓과 2년마다 11월에 열리는 빛 축제 ‘루미에르’ 때 붐빕니다. 학기 중 졸업식 기간엔 숙소가 빨리 찹니다.|Busy for the December Christmas market and the biennial Lumiere light festival in November; rooms fill fast around graduations.' },
  czestochowa: { n: '8월 15일 성모 승천 대축일 무렵엔 도보 순례단이 몰려 숙소가 빨리 찹니다.|Around the Assumption on 15 August, walking pilgrimages pour in and rooms fill early.' },
  lodz: { n: '가을 ‘빛의 축제’ 때 건물마다 조명 작품이 걸립니다.|Buildings light up with installations during the autumn Light Move Festival.' },
  malbork: { n: '7월 ‘말보르크 포위전’ 재현 축제 때 붐빕니다. 겨울엔 성 운영 시간이 짧습니다.|July’s Siege of Malbork re-enactment draws crowds; the castle keeps shorter hours in winter.' },
  lublin: { n: '7월 말 ‘카르나발 스크툼’ 거리 공연 축제 때 구시가가 붐빕니다. 봄·가을이 걷기 좋습니다.|The old town fills up for the Carnaval Sztukmistrzów street-performance festival in late July; spring and autumn are best for walking.' },
  nitra: { n: '봄·가을이 걷기 좋습니다. 8월 말 농업 박람회 아그로콤플렉스 때 숙소가 빨리 찹니다.|Spring and autumn are best for walking; rooms go fast during the Agrokomplex fair in late August.' },
  bardejov: { n: '여름에 목조 성당과 야외 박물관 구경이 좋습니다. 8월 말 장터 축제 때 광장이 붐빕니다.|Summer is best for the wooden churches and the open-air museum; the square is busy for the late-August market fair.' },
  levoca: { n: '스피시 성은 대체로 4월~11월에만 엽니다. 7월 초 마리아 언덕 대순례 때는 매우 붐빕니다.|Spiš Castle is usually open only April to November; the early-July pilgrimage to Marian Hill brings big crowds.' },
  'banska-stiavnica': { n: '12월 둘째 주말쯤 성 바르바라 축일에 광부 행진이 열리고, 9월 초엔 ‘살라만데르’ 광부 축제가 열립니다. 언덕길이 많아 겨울엔 미끄럽습니다.|Miners parade around St Barbara’s Day in December and for the Salamander festival in early September; the steep streets get icy in winter.' },
  korcula: { n: '쾌속선과 모레슈카 공연, 바디야행 배는 대체로 봄~가을에만 다닙니다. 겨울엔 배편이 크게 줄어듭니다.|The catamarans, Moreška shows and Badija boats mostly run spring to autumn; winter sailings are much reduced.' },
  sibenik: { n: '여름엔 크르카 국립공원이 매우 붐비니 아침 일찍 가세요. 봄·가을이 걷기 좋습니다.|Krka is very crowded in summer, so go early; spring and autumn are best for walking.' },
  porec: { n: '여름엔 해변 리조트 손님으로 붐비고, 겨울엔 식당과 상점이 많이 쉽니다. 가을은 모토분 송로버섯 철입니다.|Summer is busy with beach-resort guests and many places close in winter; autumn is truffle season around Motovun.' },
  pula: { n: '7·8월엔 아레나에서 콘서트와 풀라 영화제가 열려 붐빕니다. 브리유니 배와 카메냐크는 여름이 가장 좋습니다.|July and August bring concerts and the Pula Film Festival to the Arena; Brijuni and Kamenjak are best in summer.' },
  tihany: { n: '라벤더는 6월 중순~7월에 피고, 7·8월엔 호숫가가 붐빕니다. 겨울엔 식당과 배가 많이 쉽니다.|The lavender blooms mid-June to July and the lakeshore is busy in July and August; in winter many restaurants and boats stop.' },
  clervaux: { n: '‘인간 가족’ 전시는 12월 30일부터 2월 말까지 쉬니 그 사이엔 피하세요. 가을 숲 단풍이 아름답습니다.|The Family of Man closes from 30 December to the end of February, so avoid those weeks; the autumn woods are lovely.' },
  olomouc: { n: '관광객이 적어 계절을 가리지 않습니다. 스바티 코페체크는 시내가 잘 보이는 맑은 날 가세요.|Few crowds at any season; save Svatý Kopeček for a clear day with a view.' },
  mechelen: { n: '도시가 작아 하루면 충분하고 브뤼셀·안트베르펜 사이라 언제든 들르기 좋습니다. 대성당 탑은 날씨가 맑은 날 오르세요.|Small enough for a day and handy between Brussels and Antwerp at any time of year; climb the tower on a clear day.' },
  leiden: { n: '3월 중순~5월 초엔 레이던 중앙역에서 쾨켄호프 튤립 공원행 버스가 다닙니다. 10월 3일 해방 기념 축제 때는 시내가 붐비고 식물원이 쉽니다.|From mid-March to early May buses run from Leiden Centraal to the Keukenhof tulip gardens. The town is packed for the 3 October relief festival, when the botanical garden closes.' },
  chur: { n: '여름(6~9월)엔 라인 협곡 산책과 산행이 좋고, 겨울엔 빙하특급·베르니나 특급의 설경이 좋습니다.|Summer (June–September) suits the Rhine Gorge and the hills; winter brings snowy views from the Glacier and Bernina Express.' },
  bellinzona: { n: '봄(4~5월)과 가을이 걷기 좋습니다. 11월 9일~3월 18일엔 카스텔그란데만 안을 볼 수 있고 나머지 두 성은 안뜰만 엽니다.|Spring (April–May) and autumn are best for walking. From 9 November to 18 March only Castelgrande is open inside; the other two castles open just their courtyards.' },
  kandersteg: { n: '여름(6~9월)이 가장 좋고 외시넨 호수는 겨울엔 얼어서 스케이트를 탑니다. 11월엔 케이블카 대부분이 쉽니다.|Summer (June–September) is best; in winter the Oeschinensee freezes for skating. Most lifts pause in November.' },
  'st-gallen': { n: '여름(6~9월)엔 아펜첼 산행과 드라이 바이렌 수영이 좋습니다. 산 케이블카는 11월과 4월에 정비로 쉬는 때가 많습니다.|Summer (June–September) suits Appenzell hikes and swims at Drei Weieren; the mountain lifts often pause for servicing in November and April.' },
  locarno: { n: '봄(4~5월)과 초가을이 걷기 좋고, 8월엔 영화제로 숙소가 매우 비쌉니다. 성과 식물원은 겨울에 닫습니다.|Spring (April–May) and early autumn are best for walking; the August film festival makes rooms very expensive. The castle and the island garden close in winter.' },
  lauterbrunnen: { n: '하이킹은 6월 중순~9월, 폭포는 눈이 녹는 5~7월에 가장 세찹니다. 트뤼멜바흐 폭포는 11월~3월에 닫습니다.|Hike mid-June to September; the falls are fullest with snowmelt in May–July. The Trümmelbach Falls close November–March.' },
  klagenfurt: { n: '여름(6~8월)엔 뵈르터 호수에서 수영할 수 있습니다. 미니문두스와 호흐오스터비츠 성은 11월부터 3월까지 쉽니다.|In summer (June–August) you can swim in the Wörthersee; Minimundus and Hochosterwitz close from November to March.' },
  bregenz: { n: '7월 중순~8월 중순 브레겐츠 페스티벌 때 숙소가 빨리 찹니다. 호수 유람선은 봄~가을에 다닙니다.|Rooms fill fast during the Bregenz Festival from mid-July to mid-August; lake boats run from spring to autumn.' },
  kitzbuhel: { n: '1월엔 하넨캄 활강 경기로 숙소가 매우 비쌉니다. 여름(6~9월)엔 산행과 호수 수영이 좋습니다.|In January the Hahnenkamm race makes rooms very expensive; summer (June–September) is for hiking and lake swims.' },
  'zell-am-see': { n: '여름(6~9월)엔 호수와 고산 댐이 좋고, 겨울엔 스키장이 됩니다. 고산 댐은 5월 말~10월 초에만 엽니다.|Summer (June–September) suits the lake and the high reservoirs; in winter it is a ski resort. The reservoirs open only from late May to early October.' },
  werfen: { n: '얼음 동굴은 5~10월에만 열고, 성은 4월~11월 초에 엽니다.|The ice cave opens May–October only; the castle April to early November.' },
  'bad-ischl': { n: '황제 별장은 5~10월에 열고 11~12월엔 대림절 주말에만 엽니다.|The Kaiservilla opens May–October, and in November and December only on Advent weekends.' },
  durnstein: { n: '4월엔 살구꽃이 피고 9~10월은 포도 수확철입니다. 유람선은 3월 말~11월 초에만 다닙니다.|Apricot trees blossom in April and the grape harvest is in September–October; boats run only from late March to early November.' },
  linz: { n: '9월 초 아르스 일렉트로니카 축제 때 도시 곳곳에서 미디어 아트 전시가 열립니다.|During the Ars Electronica Festival in early September, media-art shows spread across the city.' },
  aegina: { n: '여름 주말엔 아테네 사람들로 배가 붐빕니다. 9월엔 피스타치오 축제가 열립니다.|Summer weekend boats are packed with Athenians; a pistachio festival is held in September.' },
  gruyeres: { n: '9~10월엔 소 떼가 산에서 내려오는 축제가 근처 마을에서 열립니다.|In September–October, villages nearby hold festivals as the cows come down from the pastures.' },
  whitby: { n: '봄과 10월 말 고스 위크엔드 때 매우 붐빕니다. 수도원과 박물관은 겨울에 여는 날이 줄어듭니다.|Very busy during the spring and late-October Goth Weekends; the abbey and museum open fewer days in winter.' },
  mikulov: { n: '9월 팔라바 포도 수확 축제 때 마을이 가장 붐빕니다.|The town is busiest during the Pálava grape-harvest festival in September.' },
  telc: { n: '겨울(11~3월)엔 성에서 겨울 투어만 운영합니다. 여름엔 광장에서 공연과 축제가 열립니다.|From November to March the castle runs only its winter tour; summer brings concerts and festivals to the square.' },
  tomar: { n: '4년마다 7월 초 타불레이루스 축제가 열립니다(다음은 2027년). 그때는 숙소가 일찍 찹니다.|The Festa dos Tabuleiros is held every four years in early July (next in 2027), when rooms fill early.' },
  sitges: { n: '2월 카니발과 10월 시체스 영화제 때 매우 붐빕니다. 해수욕은 6~9월이 좋습니다.|Very busy during the February Carnival and the October film festival; swim from June to September.' },
  tarragona: { n: '9월 산타 테클라 축제 때 사람 탑(카스텔) 쌓기가 열립니다.|Human towers (castells) rise during the Santa Tecla festival in September.' },
  cuenca: { n: '부활절 성주간 행렬이 유명합니다. 여름 낮엔 덥고 겨울은 춥고 건조합니다.|Its Holy Week processions are famous; summer days are hot and winters cold and dry.' },
  cochem: { n: '9~10월 포도 수확철엔 와인 축제가 이어집니다. 성과 엘츠 성은 11월 초까지가 정상 운영 기간입니다.|Wine festivals follow the harvest in September–October; the castle and Eltz Castle keep full hours until early November.' },
  rudesheim: { n: '유람선과 케이블카는 4~10월이 중심입니다. 겨울엔 문을 닫는 주점과 가게가 많습니다.|Cruises and the cable car run mainly April–October; many taverns and shops close in winter.' },
  'garmisch-partenkirchen': { n: '겨울엔 스키 마을이 되고, 여름(6~9월)이 산길 걷기에 가장 좋습니다. 추크슈피체는 맑은 날을 고르세요.|A ski resort in winter; June–September is best for hiking. Pick a clear day for the Zugspitze.' },
  berchtesgaden: { n: '호수가 얼면 배가 쉽니다. 켈슈타인하우스는 2026년 10월 화재로 소실돼 당분간 갈 수 없습니다.|Boats stop if the lake freezes. The Kehlsteinhaus was destroyed by fire in October 2026 and cannot be visited for now.' },
  regensburg: { n: '12월엔 구시가 곳곳과 투른 운트 탁시스 궁전 마당에서 크리스마스 마켓이 열립니다.|In December, Christmas markets fill the old town and the Thurn und Taxis palace courtyard.' },
  wurzburg: { n: '봄~가을엔 마인 강변과 포도밭에서 와인 축제가 이어집니다. 레지덴츠는 겨울엔 일찍 닫습니다.|Wine festivals run along the river and in the vineyards from spring to autumn; the Residenz closes earlier in winter.' },
  bamberg: { n: '여름엔 언덕 위 맥주 정원(켈러)이 문을 엽니다. 겨울엔 짧은 해에 맞춰 일찍 움직이세요.|In summer the hillside beer gardens (Keller) open; in winter, set off early for the short days.' },
  colmar: { n: '11월 말~12월 크리스마스 마켓 때 매우 붐비고 숙소가 빨리 찹니다.|The Christmas markets from late November make it very busy, and rooms fill early.' },
  cadiz: { n: '2월 카니발 때 숙소가 빨리 차고 매우 붐빕니다.|Rooms fill fast and the streets are packed during the February Carnival.' },
  szentendre: { n: '여름 주말엔 부다페스트 당일 손님으로 붐빕니다. 스칸젠은 4~10월이 성수기입니다.|Summer weekends are busy with day-trippers from Budapest; the Skanzen’s main season is April–October.' },
  hydra: { n: '섬에는 자동차가 없어 걷거나 당나귀·물 택시를 탑니다. 겨울엔 배편과 문을 연 가게가 줄어듭니다.|There are no cars: walk, ride a donkey or take a water taxi. In winter, sailings and open shops thin out.' },
  avila: { n: '해발 약 1,130m로 겨울이 매우 춥습니다. 성주간 행렬과 10월 산타 테레사 축제 때 붐빕니다.|At about 1,130 m the winters are bitterly cold; busy during the Holy Week processions and the October St Teresa festival.' },
  giverny: { r: '---o+++++o--', n: '모네의 집과 정원은 대략 4월부터 11월 초까지만 엽니다.|Monet’s house and gardens open only from about April to early November.' },
  bayeux: { n: '6월 초 노르망디 상륙 기념 주간에는 해변 일대가 붐빕니다.|The D-Day anniversary week in early June is busy around the beaches.' },
  ajaccio: { r: '-ooo++oo++o-', n: '7~8월은 덥고 가장 붐빕니다. 겨울에는 보트 투어가 거의 없습니다.|July–August is hot and busiest; boat trips barely run in winter.' },
  bonifacio: { r: '---o++oo++--', n: '11~3월은 호텔·식당·보트 투어 다수가 쉽니다.|Many hotels, restaurants and boat trips close from November to March.' },
  calvi: { r: '---o++oo++--', n: '11~3월은 호텔·식당 다수가 쉽니다.|Many hotels and restaurants close from November to March.' },
  chamonix: { r: '+++o-o+++o-o', n: '12~4월은 스키, 6월 말~9월은 하이킹 철입니다. 5월과 11월에는 리프트 다수가 정비로 쉽니다. 기온은 마을 기준이며 산 위는 훨씬 춥습니다.|Ski season runs December–April and hiking late June–September; many lifts close for maintenance in May and November. Temperatures are for the valley; it is far colder up high.' },
  cannes: { n: '5월 영화제 기간에는 숙소 구하기가 어렵습니다.|Rooms are scarce during the film festival in May.' },
  monaco: { n: '그랑프리 주간(2026년부터 6월 초)에는 도로가 통제되고 숙박비가 크게 오릅니다.|During Grand Prix week (early June from 2026) roads close and prices soar.' },
  'monte-carlo': { n: '그랑프리 주간(2026년부터 6월 초)에는 도로가 통제되고 숙박비가 크게 오릅니다.|During Grand Prix week (early June from 2026) roads close and prices soar.' },
  // United Kingdom
  edinburgh: { n: '8월 페스티벌 기간에는 도시가 가장 붐비고 숙박비가 크게 오릅니다.|August festivals bring the biggest crowds and the highest room rates.' },
  'isle-of-skye': { n: '6~8월에는 깔따구(미지)가 많습니다. 겨울에는 숙소와 식당 다수가 쉽니다.|Midges are thick in June–August; many places to stay and eat close in winter.' },
  // Netherlands
  amsterdam: { r: '...+........', n: '튤립은 3월 말~5월 초가 제철입니다. 4월 27일 왕의 날에는 시내가 매우 혼잡합니다.|Tulip season runs late March to early May; the city is packed on King’s Day, 27 April.' },
  // Norway, Finland, Sweden, Denmark
  bergen: { n: '연중 비가 잦아 우비가 필수입니다. 5월이 비교적 맑습니다.|It rains year-round, so bring a waterproof; May is comparatively dry.' },
  tromso: { r: 'o++o-++ooooo', n: '오로라는 9월~3월, 백야는 5월 하순~7월 하순입니다. 11월 말~1월 중순에는 해가 뜨지 않습니다.|Northern lights from September to March, midnight sun from late May to late July; the sun does not rise from late November to mid-January.' },
  stavanger: { n: '프레이케스톨렌 등산은 5~9월이 적기입니다. 겨울에는 눈과 얼음으로 가이드 동행을 권합니다.|Preikestolen is best hiked May–September; in winter, snow and ice make a guide advisable.' },
  rovaniemi: { r: '+++o-ooo+-o+', n: '눈과 오로라는 12~3월이 제철입니다. 12월은 가장 붐비고 비쌉니다.|Snow and northern lights peak December–March; December is the busiest and priciest month.' },
  kiruna: { r: '+++o-ooo+--+', n: '오로라는 9월~3월, 백야는 6~7월입니다. 해마다 새로 짓는 아이스호텔 건물은 12월~4월 초에만 있고, 연중 운영하는 얼음 객실(아이스호텔 365)은 여름에도 묵을 수 있습니다.|Northern lights September–March, midnight sun June–July; the seasonal Icehotel stands only from December to early April, but the year-round Icehotel 365 ice suites can be booked in summer too.' },
  copenhagen: { n: '티볼리는 1~3월 대부분 휴장합니다.|Tivoli is closed for most of January–March.' },
  // Austria, Hungary, Czechia
  vienna: { r: '...........o', n: '11월 중순~12월은 크리스마스 마켓 철입니다.|Christmas markets run from mid-November through December.' },
  salzburg: { r: '...........o', n: '7월 하순~8월 잘츠부르크 페스티벌 기간에는 숙박비가 오릅니다. 12월에는 크리스마스 마켓이 열립니다.|Room rates rise during the Salzburg Festival (late July–August); Christmas markets run in December.' },
  innsbruck: { n: '12~3월은 주변 스키장 시즌입니다.|December–March is ski season in the surrounding resorts.' },
  hallstatt: { n: '여름 낮에는 당일 관광객으로 매우 붐빕니다. 이른 아침이나 저녁이 한적합니다.|Summer middays are overrun with day-trippers; early morning and evening are calmer.' },
  budapest: { r: '...........o', n: '7~8월은 30도를 넘는 날이 많습니다. 12월에는 크리스마스 마켓이 열립니다.|July–August often tops 30°C; Christmas markets run in December.' },
  prague: { r: '...........o', n: '12월 크리스마스 마켓과 부활절 전후가 특히 붐빕니다.|December’s Christmas markets and the Easter period are especially busy.' },
  'cesky-krumlov': { r: '---.......--', n: '성 내부 관람은 대체로 4~10월에만 가능합니다.|Castle interiors are generally open only from April to October.' },
  'karlovy-vary': { n: '7월 초 국제영화제 기간에는 숙소가 일찍 찹니다.|Rooms fill early for the international film festival in early July.' },
  // Switzerland, Germany
  zermatt: { r: '++++-o+++o-+', n: '스키는 12~4월, 하이킹은 7~9월이 제철입니다. 5월과 11월에는 리프트 일부가 정비로 쉽니다. 산 위는 표보다 훨씬 춥습니다.|Ski December–April, hike July–September; some lifts close for maintenance in May and November. It is far colder up the mountain than the table shows.' },
  interlaken: { n: '융프라우요흐 열차는 연중 다니지만 고지대 하이킹은 6월 중순~9월에만 가능합니다.|Jungfraujoch trains run all year, but high trails are open only from mid-June to September.' },
  munich: { r: '...........o', n: '9월 하순~10월 초 옥토버페스트 기간에는 숙박비가 급등합니다.|Room rates soar during Oktoberfest, late September to early October.' },
  cologne: { r: '...........o', n: '2월 카니발과 12월 크리스마스 마켓 때 가장 붐빕니다.|Busiest during Carnival in February and the December Christmas markets.' },
  nuremberg: { r: '...........o', n: '12월 크리스마스 마켓(크리스트킨들마르크트)이 유명합니다.|Famous for its December Christmas market (Christkindlesmarkt).' },
  dresden: { r: '...........o', n: '12월에는 슈트리첼마르크트 크리스마스 마켓이 열립니다.|The Striezelmarkt Christmas market runs in December.' },
  // Ireland, Iceland, more of the United Kingdom
  dublin: { n: '3월 17일 성 패트릭의 날 전후에는 붐비고 숙박비가 오릅니다.|Crowds and room rates peak around St Patrick’s Day, 17 March.' },
  reykjavik: { r: 'ooo-o+++oo-o', n: '오로라는 9월~3월, 백야는 6~7월입니다. 한겨울에는 낮이 4~5시간뿐입니다.|Northern lights from September to March, midnight sun in June–July; midwinter has only 4–5 hours of daylight.' },
  vik: { r: 'ooo-o+++oo-o', n: '겨울에는 눈과 강풍으로 1번 국도가 통제되는 날이 있습니다.|In winter, snow and gales sometimes close the Ring Road.' },
  selfoss: { r: 'ooo-o+++oo-o', n: '오로라는 9월~3월에 볼 수 있습니다. 겨울에는 낮이 짧아 골든 서클을 하루에 돌기 빠듯합니다.|Northern lights from September to March; short winter days make the Golden Circle a tight day trip.' },
  husavik: { r: '.....+++....', n: '고래 관찰 투어는 봄부터 가을까지 다니며 6~8월이 가장 좋습니다.|Whale-watching tours run from spring to autumn and are best in June–August.' },
  'lake-district': { n: '기온은 호숫가 마을 기준입니다. 산 위는 더 춥고 날씨가 빠르게 바뀝니다.|Temperatures are for the lakeside towns; the fells are colder and the weather turns quickly.' },
  snowdonia: { n: '기온은 산 아래 마을 기준입니다. 정상은 훨씬 춥고 바람이 셉니다.|Temperatures are for the valley villages; summits are much colder and windier.' },
  // More of Germany, Switzerland, Liechtenstein
  berlin: { r: '...........o', n: '11월 말~12월에는 곳곳에서 크리스마스 마켓이 열립니다.|Christmas markets open across the city from late November through December.' },
  frankfurt: { r: '...........o', n: '12월에는 뢰머 광장에서 크리스마스 마켓이 열립니다.|The Christmas market fills the Römerberg in December.' },
  stuttgart: { r: '...........o', n: '12월에는 크리스마스 마켓이 열립니다.|The Christmas market runs in December.' },
  leipzig: { r: '...........o', n: '12월에는 크리스마스 마켓이 열립니다.|The Christmas market runs in December.' },
  rothenburg: { r: '...........o', n: '12월에는 크리스마스 마켓(라이터를레스마르크트)이 열립니다.|The Reiterlesmarkt Christmas market runs in December.' },
  'st-moritz': { r: '+++o-o+++o-+', n: '스키는 12월~4월 초, 하이킹은 7~9월이 제철입니다. 5월과 11월에는 리프트와 호텔 다수가 쉽니다. 기온은 마을 기준이며 산 위는 훨씬 춥습니다.|Ski December to early April, hike July–September; many lifts and hotels close in May and November. Temperatures are for the village; it is far colder up high.' },
  grindelwald: { r: '+++o-++++o-+', n: '스키는 12~3월, 하이킹은 6월 중순~9월이 제철입니다. 5월과 11월에는 리프트와 호텔 다수가 쉽니다. 기온은 마을 기준이며 산 위는 훨씬 춥습니다.|Ski December–March, hike mid-June to September; many lifts and hotels close in May and November. Temperatures are for the village; it is far colder up high.' },
  montreux: { n: '7월 초 재즈 페스티벌 기간에는 숙소가 일찍 찹니다.|Rooms fill early for the jazz festival in early July.' },
  malbun: { r: '+++........+', n: '12월 중순~3월은 스키, 여름은 하이킹 철입니다. 기온은 마을 기준입니다.|Mid-December to March is ski season and summer is for hiking. Temperatures are for the village.' },
  // Italy, Vatican
  rome: { n: '8월 중순 페라고스토 전후에는 휴가로 문 닫는 동네 식당과 상점이 많습니다.|Many neighbourhood restaurants and shops close around Ferragosto in mid-August.' },
  'vatican-city': { n: '부활절과 성탄절 전후에는 특히 붐빕니다.|Especially crowded around Easter and Christmas.' },
  venice: { n: '2월 카니발 기간에 매우 붐빕니다. 늦가을~겨울에는 아쿠아 알타(침수)가 생기는 날이 있습니다.|Very crowded during Carnival in February; acqua alta flooding can occur in late autumn and winter.' },
  siena: { n: '7월 2일과 8월 16일 팔리오 경마 때는 숙소가 일찍 차고 광장이 통제됩니다.|For the Palio on 2 July and 16 August rooms sell out early and the square is closed off.' },
  verona: { n: '6~9월 아레나 오페라 축제 기간에는 공연 날 저녁이 붐빕니다.|Evenings are busy on performance days during the Arena opera festival, June–September.' },
  pompeii: { n: '유적에는 그늘이 거의 없어 한여름 낮 관람은 힘듭니다.|There is almost no shade in the ruins, so summer middays are punishing.' },
  'cinque-terre': { r: '--o.......o-', n: '큰비가 오면 해안 트레일이 닫힙니다. 마을을 잇는 배는 봄부터 가을까지만 다닙니다.|Coastal trails close after heavy rain; boats between the villages run only from spring to autumn.' },
  positano: { r: '--o........-', n: '11~3월에는 호텔·식당 다수가 쉬고 배편이 줄어듭니다.|Many hotels and restaurants close and boats run less often from November to March.' },
  amalfi: { r: '--o........-', n: '11~3월에는 호텔·식당 다수가 쉬고 배편이 줄어듭니다.|Many hotels and restaurants close and boats run less often from November to March.' },
  capri: { r: '--o........-', n: '11~3월에는 호텔·식당 다수가 쉬고 배편이 줄어듭니다.|Many hotels and restaurants close and boats run less often from November to March.' },
  cortina: { r: '+++o-o+++o-+', n: '스키는 12~3월, 하이킹은 6월 말~9월이 제철입니다. 5월과 11월에는 리프트와 호텔 다수가 쉽니다. 기온은 마을 기준이며 산 위는 훨씬 춥습니다.|Ski December–March, hike late June to September; many lifts and hotels close in May and November. Temperatures are for the village; it is far colder up high.' },
  // Spain, Andorra, Portugal
  seville: { r: '++.........+', n: '부활절 성주간과 4월 축제(페리아) 때는 매우 붐비고 숙박비가 크게 오릅니다. 7~8월은 40도 안팎까지 오릅니다.|Holy Week and the April Fair bring big crowds and steep prices; July–August reaches around 40°C.' },
  cordoba: { r: '.+..........', n: '5월 파티오 축제 기간이 가장 붐빕니다.|Busiest during the Patios festival in May.' },
  malaga: { r: '++.........+' },
  valencia: { n: '3월 중순 파야스 축제(15~19일) 기간에는 도시 전체가 매우 붐비고 시끄럽습니다.|The whole city is packed and noisy during Las Fallas, 15–19 March.' },
  'pas-de-la-casa': { r: '++++.......+', n: '12월~4월 중순은 스키 철입니다. 기온은 마을 기준입니다.|December to mid-April is ski season. Temperatures are for the village.' },
  ordino: { r: 'ooo........o', n: '겨울에는 오르디노 아르칼리스 스키장이 열립니다.|The Ordino Arcalís ski area operates in winter.' },
  lisbon: { n: '6월 성 안토니우 축제(12~13일 절정) 때 구시가가 매우 붐빕니다.|The old town is packed for the St Anthony festivities, peaking on 12–13 June.' },
  porto: { n: '6월 23~24일 상 주앙 축제 때 매우 붐빕니다.|Very crowded for the São João festival on 23–24 June.' },
  fatima: { n: '5월 13일과 10월 13일 전후에는 순례객으로 매우 붐빕니다.|Pilgrims crowd the town around 13 May and 13 October.' },
  nazare: { n: '큰 파도는 대체로 10월~3월에 옵니다. 해수욕은 여름이 제철입니다.|The giant waves mostly come between October and March; summer is beach season.' },
  funchal: { r: '++......++.+', n: '연중 온화합니다. 연말 불꽃놀이 기간에는 숙소가 일찍 찹니다.|Mild all year; rooms fill early for the New Year fireworks.' },
  // Poland, Slovakia, Baltics
  krakow: { r: '...........o', n: '12월에는 중앙 광장에서 크리스마스 마켓이 열립니다.|The Christmas market fills the main square in December.' },
  wroclaw: { r: '...........o', n: '12월에는 크리스마스 마켓이 열립니다.|The Christmas market runs in December.' },
  gdansk: { n: '7월 말~8월 중순 성 도미니크 장터 기간에 가장 붐빕니다.|Busiest during St Dominic’s Fair, late July to mid-August.' },
  zakopane: { r: '++o........+', n: '12~3월은 스키, 7~8월은 등산 성수기입니다. 기온은 마을 기준이며 산 위는 훨씬 춥습니다.|December–March is ski season and July–August is peak hiking. Temperatures are for the town; it is far colder up high.' },
  bratislava: { r: '...........o', n: '12월에는 크리스마스 마켓이 열립니다.|The Christmas market runs in December.' },
  poprad: { n: '하이 타트라의 높은 등산로는 겨울철에 폐쇄됩니다.|High trails in the High Tatras are closed in the winter season.' },
  tallinn: { r: '...........o', n: '12월에는 시청 광장에서 크리스마스 마켓이 열립니다.|The Christmas market fills Town Hall Square in December.' },
  riga: { r: '...........o', n: '12월에는 구시가에서 크리스마스 마켓이 열립니다.|The Christmas market runs in the old town in December.' },
  // Greece, Cyprus
  athens: { n: '한여름 폭염 때는 아크로폴리스가 낮 시간에 문을 닫는 날이 있습니다.|In summer heatwaves the Acropolis sometimes closes during the hottest hours.' },
  santorini: { r: '--o.......o-', n: '7~8월이 가장 붐빕니다. 11~3월에는 호텔·식당 다수가 쉬고 배편이 줄어듭니다.|Busiest in July–August. Many hotels and restaurants close and boats run less often from November to March.' },
  mykonos: { r: '---.......--', n: '7~8월에는 강한 북풍(멜테미)이 자주 붑니다. 11~3월에는 호텔·식당 다수가 쉬고 배편이 줄어듭니다.|The strong meltemi wind often blows in July–August. Many hotels and restaurants close and boats run less often from November to March.' },
  naxos: { r: '---.......--', n: '11~3월에는 호텔·식당 다수가 쉬고 배편이 줄어듭니다.|Many hotels and restaurants close and boats run less often from November to March.' },
  zakynthos: { r: '---.......--', n: '11~3월에는 호텔·식당 다수가 쉬고 배편이 줄어듭니다.|Many hotels and restaurants close and boats run less often from November to March.' },
  'ayia-napa': { r: '--o...o...o-', n: '11~3월에는 리조트와 식당 다수가 쉽니다.|Many resorts and restaurants close from November to March.' },
  // Balkans, Türkiye, Bulgaria, Romania, Georgia
  zagreb: { r: '...........o', n: '12월에는 도심 곳곳에서 어드벤트(크리스마스 마켓)가 열립니다.|Advent markets fill the city centre in December.' },
  dubrovnik: { n: '6~9월 크루즈선이 들어오는 날에는 구시가가 매우 혼잡합니다.|The old town is very crowded on cruise-ship days from June to September.' },
  hvar: { r: '--o.......o-', n: '11~3월에는 호텔·식당 다수가 쉬고 배편이 줄어듭니다.|Many hotels and restaurants close and boats run less often from November to March.' },
  plitvice: { n: '겨울에는 눈과 얼음으로 일부 구간이 닫힙니다.|Parts of the park close in winter because of snow and ice.' },
  postojna: { n: '동굴 안은 연중 10도 안팎이라 여름에도 겉옷이 필요합니다.|The cave stays around 10°C all year, so bring a layer even in summer.' },
  kotor: { n: '여름에 크루즈선이 들어오는 날에는 구시가가 매우 혼잡합니다.|The old town is very crowded on summer cruise-ship days.' },
  goreme: { n: '열기구는 연중 뜨지만 바람이 세면 취소되므로 하루 이상 여유를 두세요. 겨울에는 눈이 옵니다.|Balloons fly all year but are cancelled in wind, so allow a spare day; it snows in winter.' },
  nessebar: { r: '---.......--', n: '해변 철은 6~9월입니다. 겨울에는 호텔과 식당 다수가 쉽니다.|Beach season is June–September; many hotels and restaurants close in winter.' },
  sibiu: { r: '...........o', n: '12월에는 큰 광장에서 크리스마스 마켓이 열립니다.|The Christmas market fills the Large Square in December.' },
  stepantsminda: { n: '겨울에는 눈으로 조지아 군사 도로가 통제되는 날이 있습니다. 기온은 마을 기준입니다.|In winter, snow sometimes closes the Georgian Military Highway. Temperatures are for the village.' },
  batumi: { n: '연중 비가 잦습니다. 해수욕은 7~9월이 제철입니다.|It rains often all year; swimming season is July–September.' },
  // Isle of Man, Channel Islands, Faroes, Greenland, Russia
  douglas: { n: '5월 말~6월 초 TT 오토바이 경주 기간에는 배와 숙소가 일찍 차고, 경주가 열리는 시간에는 코스 도로가 막힙니다.|During the TT motorcycle races (late May to early June) ferries and rooms book up early, and the course roads close while racing is on.' },
  'st-helier': { n: '8월 둘째 금·토요일 꽃 축제(배틀 오브 플라워스) 때는 숙소가 일찍 찹니다.|Rooms go early for the Battle of Flowers on the second Friday and Saturday of August.' },
  sark: { n: '11월~3월에는 건지에서 오는 배가 하루 1~2편으로 줄어 당일치기가 어려운 날이 있습니다. 저지에서 오는 배는 4월 말~9월에만 다닙니다.|From November to March, sailings from Guernsey drop to one or two a day, so some days rule out a day trip; boats from Jersey run only from late April to September.' },
  torshavn: { n: '7월 28~29일 국경일 올라브쇠카에는 시내 전체가 축제 분위기이고 숙소가 빨리 찹니다.|The national festival Ólavsøka on 28–29 July fills the town and its rooms.' },
  vagar: { r: '....o+++....', n: '미키네스섬은 5월 1일~8월 31일에만 들어갈 수 있고 퍼핀도 이때만 있습니다. 배는 미리 예약하고, 마을 밖 하이킹은 따로 요금을 냅니다.|Mykines can be visited only from 1 May to 31 August, which is also puffin season; book the ferry ahead and expect a separate fee to hike beyond the village.' },
  nuuk: { n: '오로라는 9월~3월 맑은 밤에 볼 수 있습니다. 6월 21일은 그린란드 국경일입니다.|Northern lights show on clear nights from September to March; 21 June is Greenland’s National Day.' },
  ilulissat: { r: 'o++oo+++o---', n: '백야는 5월 하순~7월 하순, 해가 뜨지 않는 극야는 11월 말~1월 중순입니다. 오로라는 9월~3월, 개썰매는 2~4월이 제철입니다.|Midnight sun from late May to late July; the sun stays down from late November to mid-January. Northern lights September–March, dog sledding February–April.' },
  kangerlussuaq: { r: 'ooo.....+o..', n: '오로라는 9월~4월 초에 볼 수 있고, 건조한 내륙이라 맑은 밤이 많습니다. 겨울에는 영하 15도 아래로 자주 내려갑니다.|Northern lights from September to early April, and the dry inland climate gives many clear nights; winter often drops below −15°C.' },
  'saint-petersburg': { n: '백야는 6월 중순 전후로, 이때 가장 붐빕니다. 4월 10일~11월 30일에는 밤마다 네바강 다리가 들려 새벽에는 강을 건널 수 없으니 숙소 위치를 확인하세요.|White nights peak around mid-June, the busiest time. From 10 April to 30 November the Neva bridges are raised every night, so you cannot cross the river in the small hours; check which bank your hotel is on.' },
  vladivostok: { n: '6~7월에는 바다 안개와 비가 잦습니다. 8월은 해수욕 철이고, 9월은 따뜻하고 한적해 가장 좋습니다.|June and July bring frequent sea fog and rain; August is beach season, and September, warm and quieter, is the best month.' },
  irkutsk: { r: '.oo.........', n: '바이칼 호수 얼음은 2월~3월 초에 가장 맑아 얼음 위 산책·스케이트 투어가 열립니다. 얼음 위에서는 현지 가이드와 다니세요.|Lake Baikal’s ice is clearest from February to early March, when ice walks and skating tours run; go with a local guide on the ice.' },
}
